let header=load("header").replace("end WaveMap",`abbrev Other {n : ℕ} (j : Fin n) := {i : Fin n // i ≠ j}
def insertCoord {n : ℕ} (j : Fin n) (y : Other j → ℝ) (z : ℝ) : X n :=
  fun i => if h : i = j then z else y ⟨i, h⟩
def otherBox {n : ℕ} (j : Fin n) (R : ℝ) : Set (Other j → ℝ) :=
  Set.pi Set.univ (fun _ => Set.Icc (-R) R)

end WaveMap`);
store("header",header);
const w="WaveMap.";
const tangency="∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t → inner ℝ (u (x, t)) (WaveMap.dt u (x, t)) = 0 ∧ inner ℝ (WaveMap.dt u (x, t)) (WaveMap.dt (WaveMap.dt u) (x, t) - WaveMap.lap u (x, t)) = 0";
const pointwise=`∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t →
  (inner ℝ (u (x, t)) (WaveMap.dt u (x, t)) = 0 ∧
   inner ℝ (WaveMap.dt u (x, t)) (WaveMap.dt (WaveMap.dt u) (x, t) - WaveMap.lap u (x, t)) = 0) ∧
  (∀ a : ℝ, WaveMap.dt (WaveMap.dt u) (x, t) - WaveMap.lap u (x, t) = a • u (x, t) →
    a = (∑ j : Fin n, ‖WaveMap.dx u j (x, t)‖ ^ 2) - ‖WaveMap.dt u (x, t)‖ ^ 2) ∧
  WaveMap.dt (WaveMap.dt u) (x, t) - WaveMap.lap u (x, t) =
    ((∑ j : Fin n, ‖WaveMap.dx u j (x, t)‖ ^ 2) - ‖WaveMap.dt u (x, t)‖ ^ 2) • u (x, t)`;
const geometry="∀ t : ℝ, 0 < t → ∃ C : Set (WaveMap.X n), ∃ R : ℝ, WaveMap.supportGeometry u q t C R";
const support=`(∀ t : ℝ, 0 < t → ∃ C : Set (WaveMap.X n), ∃ R : ℝ,
    WaveMap.supportGeometry u q t C R ∧ WaveMap.supportSections u t C R) ∧
  (∀ t : ℝ, 0 < t → Integrable (fun x : WaveMap.X n => WaveMap.density u (x, t))) ∧
  ContinuousOn (WaveMap.density u) (WaveMap.domain n) ∧
  ContinuousOn (WaveMap.densityT u) (WaveMap.domain n)`;
const densityFormula=`∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t →
  HasDerivAt (fun r : ℝ => WaveMap.density u (x, r)) (WaveMap.densityT u (x, t)) t ∧
  WaveMap.densityT u (x, t) =
    2 * WaveMap.timeProduct u (x, t) + 2 * ∑ j : Fin n, WaveMap.mixedProduct u j (x, t)`;
const bound=`∀ t : ℝ, 0 < t → ∃ η B R : ℝ,
  0 < η ∧ 0 ≤ B ∧ 0 < R ∧ η < t ∧
  Integrable ((WaveMap.box n R).indicator (fun _ => B)) ∧
  ∀ h : ℝ, 0 < |h| → |h| < η → ∀ x : WaveMap.X n,
    |WaveMap.quotient u t h x| ≤ (WaveMap.box n R).indicator (fun _ => B) x`;
const differentiating=`(∀ t : ℝ, 0 < t →
    HasDerivAt (WaveMap.energy u) (∫ x : WaveMap.X n, WaveMap.densityT u (x, t)) t ∧
    Integrable (fun x : WaveMap.X n => WaveMap.densityT u (x, t)) ∧
    Integrable (fun x : WaveMap.X n => WaveMap.timeProduct u (x, t)) ∧
    ∀ j : Fin n, Integrable (fun x : WaveMap.X n => WaveMap.mixedProduct u j (x, t))) ∧
  (∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t →
    WaveMap.densityT u (x, t) =
      2 * WaveMap.timeProduct u (x, t) + 2 * ∑ j : Fin n, WaveMap.mixedProduct u j (x, t))`;
const bridge=`∀ (j : Fin n) (R : ℝ), 0 < R → ∀ f : WaveMap.X n → ℝ,
  IntegrableOn f (WaveMap.box n R) →
  (∫ x in WaveMap.box n R, f x) =
    ∫ y in WaveMap.otherBox j R, ∫ z in Set.Icc (-R) R, f (WaveMap.insertCoord j y z)`;
const divergence=`∀ t : ℝ, 0 < t → ∀ j : Fin n,
  (∀ x : WaveMap.X n, WaveMap.fluxDx u j (x, t) =
    WaveMap.mixedProduct u j (x, t) + WaveMap.lapProduct u j (x, t)) ∧
  Integrable (fun x : WaveMap.X n => WaveMap.fluxDx u j (x, t)) ∧
  (∫ x : WaveMap.X n, WaveMap.fluxDx u j (x, t)) = 0`;
const ibp=`∀ t : ℝ, 0 < t → ∀ j : Fin n,
  (∫ x : WaveMap.X n, WaveMap.mixedProduct u j (x, t)) =
    -(∫ x : WaveMap.X n, WaveMap.lapProduct u j (x, t)) ∧
  Integrable (fun x : WaveMap.X n => WaveMap.mixedProduct u j (x, t)) ∧
  Integrable (fun x : WaveMap.X n => WaveMap.lapProduct u j (x, t))`;
const zero=`∀ t : ℝ, 0 < t →
  Integrable (fun x : WaveMap.X n => WaveMap.density u (x, t)) ∧
  DifferentiableAt ℝ (WaveMap.energy u) t ∧ deriv (WaveMap.energy u) t = 0`;
const conclusion=`(${zero}) ∧
  ∀ s t : ℝ, 0 < s → 0 < t → WaveMap.energy u s = WaveMap.energy u t`;
const artifact={
header,
parameters:load("parameters"),
premise_types:{
H001:"1 ≤ n ∧ 1 ≤ m",
H002:"ContDiffOn ℝ ((⊤ : ℕ∞) : WithTop ℕ∞) u (WaveMap.domain n)",
H003:"‖q‖ = 1",
H004:"∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t → ‖u (x, t)‖ = 1",
H005:"∀ x : WaveMap.X n, ∀ t : ℝ, 0 < t → ∃ a : ℝ, WaveMap.dt (WaveMap.dt u) (x, t) - WaveMap.lap u (x, t) = a • u (x, t)",
H006:"∀ s t : ℝ, 0 < s → s < t → ∃ C : Set (WaveMap.X n), IsCompact C ∧ ∀ x : WaveMap.X n, x ∉ C → ∀ r ∈ Set.Icc s t, u (x, r) = q"
},
conclusion_type:conclusion,
representation:"Use n,m : ℕ with H001 retaining positivity; these index precisely the positive integer dimensions of the source. X n = Fin n → ℝ is the Cartesian coordinate model of ℝ^n. Its standard product topology and finite-dimensional derivative structure agree with the usual Euclidean structure, although its norm instance is the sup norm; no spatial Euclidean norm enters any source formula. Its volume is the product of one-dimensional Lebesgue measures, as defined by MeasureSpace.pi. V m = EuclideanSpace ℝ (Fin m) = PiLp 2 (fun _ => ℝ), so its norm and inner ℝ are exactly the Euclidean norm and dot product. Fin n labels coordinates 0,...,n-1, corresponding bijectively to source coordinates 1,...,n; all sums range over every coordinate. u is an arbitrary total extension to X n × ℝ; H002 and all pointwise conclusions concern only the open set t>0. Every source positive-time function admits such an extension, and restriction recovers the source; derivative locality makes its nonpositive-time values irrelevant. H002 uses the inclusion of (⊤ : ℕ∞) into WithTop ℕ∞: this is the smoothness index, not the outer top, which would require analyticity. dt is the ordinary vector derivative in time; dx applies the spatial Fréchet derivative to Pi.single j 1, the jth unit coordinate vector, and repeated dx/dt give precisely the prescribed componentwise derivatives. density has no 1/2 factor. energy is Mathlib's total real Bochner integral; T004 establishes absolute integrability before its finite-energy meaning is used in T007 or any subsequent step. No integrability or differentiability is assumed by these definitions. sectionGood, supportGeometry and supportSections only package explicit N002 clauses as predicates and do not assert them. All positive-order joint derivatives are encoded by iteratedFDeriv ℝ (k+1); under smoothness this is equivalent to vanishing of all positive-order componentwise partial derivatives. H003 is retained although unused by the supplied route. M001–M004 are implemented by direct library use, not additional premise ports; Audit A notes remain local references. The only coordinate-view change actually needed is the insertion of one coordinate in R004; T008 proves the corresponding restricted integral identity before T009 uses it.",
objects:[],
steps:[
{id:"T001",statement:tangency,inputs:["H001","H002","H004","H005"],source_steps:["S001"],explanation:"Differentiate the unit constraint in time, then use the pointwise scalar witness of H005 and dot-product symmetry. The witness is local and never differentiated."},
{id:"T002",statement:pointwise,inputs:["H001","H002","H004","H005","T001"],source_steps:["S002","S003"],explanation:"Retain T001. Twice differentiate the unit constraint in time and each coordinate, dot the normality equation with u, and sum. Prove the coefficient formula for every pointwise admissible scalar and substitute it back. This exports every clause of N001."},
{id:"T003",statement:geometry,inputs:["H001","H002","H006"],source_steps:["S004","S005","S006"],explanation:"For each t>0 choose the compact support on [t/2,3t/2], enclose it strictly in a positive box, and compute its product Lebesgue volume. On the open complement times the interior slab u is locally constant, so every positive-order joint derivative vanishes. This is support geometry only, without selecting any witness globally."},
{id:"T004",statement:support,inputs:["H001","H002","T003"],source_steps:["S006","S007","S008"],explanation:"For each compatible support witness obtain continuity, vanishing, compact-box bounds and absolute integrability for exactly the six families in N002, by a constant times the box indicator. Include joint continuity of density and its time derivative on t>0 and integrability at every positive time. Existential witnesses stay together with their section properties. Exports N002; establishes the finite-energy guard."},
{id:"T005",statement:densityFormula,inputs:["H001","H002"],source_steps:["S009"],explanation:"Apply the finite product rule and equality of mixed derivatives on the positive open domain. Supply an actual HasDerivAt assertion for density as well as the expanded derivative identity; this is the derivative used by the mean value theorem and pointwise quotient convergence."},
{id:"T006",statement:bound,inputs:["H001","H002","T004","T005"],source_steps:["S010","S011"],explanation:"At each fixed t choose η=t/4 and compatible C,R. Compactness of box × [t-η,t+η] bounds densityT by a nonnegative B depending on t and the support witnesses, uniformly in x and in the allowed increments. Use exists_hasDerivAt_eq_slope on the ordered endpoints, together with zero density off the box. The integrable dominating function is the displayed box indicator times B; η<t ensures all sampled times are positive."},
{id:"T007",statement:differentiating,inputs:["H001","H002","T004","T005","T006"],source_steps:["S012","S013","S014"],explanation:"For any sequence of nonzero increments tending to zero inside the T006 range, density quotients are measurable, integrable, dominated by the single integrable bound and converge pointwise to densityT. Apply MeasureTheory.tendsto_integral_of_dominated_convergence with real codomain and Lebesgue volume. Linearity identifies the integral quotient with the energy quotient, using T004 at both positive times. Discharge the sequence assumptions and use the sequential criterion for the punctured real limit to get HasDerivAt of energy. Retain the density formula and integrability of every displayed term. This exports N003 without assuming an integral interchange."},
{id:"T008",statement:bridge,inputs:[],source_steps:["S016"],explanation:"Prove the coordinate integration bridge for the actual insertion map and restricted boxes, under the stated IntegrableOn premise. Use the finite-product measure-preserving split (MeasureTheory.volume_preserving_piEquivPiSubtypeProd with predicate i ≠ j), evaluate its singleton complementary factor, and apply Fubini for the finite restricted measures. otherBox uses all coordinates except j in inherited order; when n=1 this is the singleton empty tuple with mass one. This is the checked conversion required by the coordinate FTC argument, not an assumption about arbitrary rearrangement of measures."},
{id:"T009",statement:divergence,inputs:["H001","H002","T004","T008"],source_steps:["S015","S016","S017","S018"],explanation:"For flux = inner dt u (dx u j), derive the spatial product rule and use N002's support to make the endpoint values vanish. Apply intervalIntegral.integral_eq_sub_of_hasDerivAt_of_le on [-R,R] for every other-coordinate tuple; smoothness and compactness give derivative interval integrability. Endpoints have zero Lebesgue measure, identifying interval and closed-set integrals. Use T008, product integrability and MeasureTheory.integral_integral to conclude the box integral of fluxDx is zero, then its whole-space integral is zero by support. Retain absolute integrability and the pointwise product rule."},
{id:"T010",statement:ibp,inputs:["H001","T004","T009"],source_steps:["S019"],explanation:"Integrate the T009 product identity by linearity, using T004 for both product integrabilities, and rearrange the zero total derivative integral. The mixedProduct convention already places dx u first using symmetry of the real Euclidean inner product. Generalize t>0 and j. Exports all of N004."},
{id:"T011",statement:zero,inputs:["H001","T002","T004","T007","T010"],source_steps:["S020","S021"],explanation:"Combine the differentiated integral identity and its expanded density with integration by parts in each finite coordinate. All terms are integrable by N002/N003/N004, allowing finite summation and integral linearity. Recombine the Laplacian and use the pointwise orthogonality of N001 to make the final integrand zero. Obtain differentiability and deriv energy = 0 at every t>0, retaining integrability."},
{id:"T012",statement:conclusion,inputs:["T011"],source_steps:["S022"],explanation:"Retain T011 and apply exists_hasDerivAt_eq_slope to energy on a positive interval with ordered endpoints. Differentiability gives continuity at the endpoints and zero derivative in the interior; slope zero gives equality of energies. Reverse endpoint order or handle equal times as needed. This is the complete P, including constancy, with no time-zero assertion."}
],
terminal:"T012",
source_outputs:{N001:"T002",N002:"T004",N003:"T007",N004:"T010",P:"T012"},
endpoint_correspondence:{P:{mode:"equivalent",explanation:"Positive integer dimensions are represented by n,m : ℕ with H001 : 1≤n ∧ 1≤m, a bijective encoding. X n is the usual real Cartesian coordinate space with product Lebesgue measure; V m has exactly the Euclidean norm and dot product. Fin n reindexes all n coordinates without changing finite sums. H002 asserts joint C∞ smoothness on precisely t>0, using the inner infinity smoothness index; H003/H004 keep both unit conditions. H005 is the original pointwise existential scalar normality equation, with no scalar field regularity. H006 retains a single compact spatial set for every entire positive closed time interval. A source map on t>0 extends arbitrarily to the total u used here, and any such u restricts back; locality preserves all positive-time derivatives and hypotheses in both directions. dt, dx and lap give the componentwise time/spatial derivatives and Laplacian, and density is exactly the unhalved sum of their Euclidean squares. T004 proves the guard that makes energy the actual finite Lebesgue integral. The conclusion explicitly asserts absolute integrability, real differentiability and zero derivative at every positive time, together with energy equality for every pair of positive times. Restriction and extension therefore give the whole source target in both directions; no conclusion at nonpositive times or additional hypothesis is present."}}
};
